topics.description:
Fetching data on the client is a classic effect: sync the component with a server. A safe pattern keeps three pieces of state (data, loading, error) and cleans up when the request is no longer wanted.

### The race condition

If `userId` changes from 1 to 2 quickly, request 1 may finish **after** request 2 and overwrite the screen with outdated data. Fix with an `ignore` flag in the cleanup:

```jsx
useEffect(() => {
  let ignore = false;
  setLoading(true);
  fetchUser(userId).then(u => { if (!ignore) { setUser(u); setLoading(false); } });
  return () => { ignore = true; };
}, [userId]);
```

With real `fetch`, prefer `AbortController`: `controller.abort()` in cleanup cancels the request, and you ignore `AbortError`.

### Checklist

- Handle **loading**, **error** and **empty** states.
- Put `userId` (anything used inside) in the dependency array.
- Cleanup stale requests.
- Do not make the effect callback `async` - it must return a cleanup function or nothing; define an async function inside instead.

### Better tools

Hand-written fetch effects miss caching, retries, deduplication and refetching. For real apps use **TanStack Query**, SWR, or framework data loaders. Keep the manual version for learning and tiny cases.

examples.code:
// Fake API: user 1 is slow (900ms), others fast (300ms)
function fakeFetchUser(id) {
  return new Promise((resolve, reject) => {
    setTimeout(() => {
      if (id === 3) reject(new Error("User 3 not found"));
      else resolve({ id, name: "User #" + id });
    }, id === 1 ? 900 : 300);
  });
}

function Profile({ id }) {
  const [state, setState] = useState({ status: "loading", user: null, error: null });

  useEffect(() => {
    let ignore = false;
    setState({ status: "loading", user: null, error: null });
    fakeFetchUser(id)
      .then((user) => { if (!ignore) setState({ status: "success", user, error: null }); })
      .catch((err) => { if (!ignore) setState({ status: "error", user: null, error: err.message }); });
    return () => { ignore = true; };
  }, [id]);

  if (state.status === "loading") return <p>Loading user {id}...</p>;
  if (state.status === "error") return <p style={{ color: "crimson" }}>{state.error}</p>;
  return <p>Loaded: <b>{state.user.name}</b></p>;
}

function App() {
  const [id, setId] = useState(1);
  return (
    <div style={{ fontFamily: "sans-serif", padding: 12 }}>
      {[1, 2, 3].map((n) => (
        <button key={n} onClick={() => setId(n)} style={{ marginRight: 6 }}>User {n}</button>
      ))}
      <Profile id={id} />
    </div>
  );
}

function Logger() {
  useEffect(() => {
    console.log("effect: setup");
    return () => console.log("effect: cleanup");
  }, []);
  console.log("render");
  return <p>Open the console tab and watch the order.</p>;
}

function App() {
  return (
    <StrictMode>
      <Logger />
    </StrictMode>
  );
}

function App() {
  const [ticks, setTicks] = useState(0);
  const [running, setRunning] = useState(false);
  const idRef = useRef(null);
  const prevRef = useRef(0);

  useEffect(() => {
    prevRef.current = ticks;
  });

  function start() {
    if (idRef.current) return;
    setRunning(true);
    idRef.current = setInterval(() => setTicks((t) => t + 1), 200);
  }
  function stop() {
    clearInterval(idRef.current);
    idRef.current = null;
    setRunning(false);
  }
  useEffect(() => () => clearInterval(idRef.current), []);

  return (
    <div style={{ fontFamily: "sans-serif", padding: 12 }}>
      <p>Now: {ticks} | Previous render: {prevRef.current}</p>
      <button onClick={start} disabled={running}>Start</button>
      <button onClick={stop} disabled={!running}>Stop</button>
    </div>
  );
}

function App() {
  const inputRef = useRef(null);
  const endRef = useRef(null);
  const [lines, setLines] = useState(["Line 1", "Line 2", "Line 3", "Line 4", "Line 5", "Line 6"]);

  useEffect(() => {
    inputRef.current.focus();
  }, []);

  function addLine(e) {
    e.preventDefault();
    const v = inputRef.current.value.trim();
    if (!v) return;
    setLines((l) => [...l, v]);
    inputRef.current.value = "";
    inputRef.current.focus();
  }
  useEffect(() => {
    endRef.current.scrollIntoView({ block: "nearest" });
  }, [lines]);

  return (
    <div style={{ fontFamily: "sans-serif", padding: 12 }}>
      <div style={{ height: 90, overflow: "auto", border: "1px solid #ccc", padding: 6 }}>
        {lines.map((l, i) => <div key={i}>{l}</div>)}
        <div ref={endRef} />
      </div>
      <form onSubmit={addLine}>
        <input ref={inputRef} placeholder="Add a line" />
        <button>Add</button>
      </form>
    </div>
  );
}

function Profile({ user }) {
  // Always call hooks first, unconditionally
  const [editing, setEditing] = useState(false);
  const label = useMemo(() => (user ? user.name.toUpperCase() : ""), [user]);

  // Early return only AFTER the hooks
  if (!user) return <p>No user</p>;

  return (
    <div>
      <b>{label}</b>{" "}
      <button onClick={() => setEditing(!editing)}>{editing ? "Done" : "Edit"}</button>
    </div>
  );
}

function App() {
  const [user, setUser] = useState(null);
  return (
    <div style={{ fontFamily: "sans-serif", padding: 12 }}>
      <button onClick={() => setUser(user ? null : { name: "Asha" })}>Toggle user</button>
      <Profile user={user} />
    </div>
  );
}

topics.description:
`useReducer` is an alternative to `useState` when state has several sub-values or when the next state depends on a named *event*. Instead of calling many setters, you **dispatch actions** and a **reducer** decides the new state.

```jsx
const [state, dispatch] = useReducer(reducer, initialState);
dispatch({ type: "added", text: "Buy milk" });
```

### The reducer

`reducer(state, action)` is a **pure function** that returns the next state. It must not mutate `state`, call APIs or generate random values.

```jsx
function reducer(state, action) {
  switch (action.type) {
    case "inc": return { ...state, count: state.count + 1 };
    case "reset": return initialState;
    default: throw new Error("Unknown action " + action.type);
  }
}
```

### When to prefer it over useState

- Many related fields that change together.
- Next state depends on previous state in non-trivial ways.
- You want all update rules in **one testable place**.
- You want to pass a single stable `dispatch` function down instead of many callbacks. `dispatch` identity never changes.

### Tips

- Describe *what happened* (`"item_added"`), not *how to set state* (`"set_items"`).
- Third argument `init` lets you compute initial state lazily.
- Combine with Context to build a small Redux-like store without a library.
- Reducer logic can be unit tested without React.

examples.code:
const initial = { count: 0, step: 1 };

function reducer(state, action) {
  switch (action.type) {
    case "inc": return { ...state, count: state.count + state.step };
    case "dec": return { ...state, count: state.count - state.step };
    case "setStep": return { ...state, step: action.step };
    case "reset": return initial;
    default: throw new Error("Unknown action: " + action.type);
  }
}

function App() {
  const [state, dispatch] = useReducer(reducer, initial);
  return (
    <div style={{ fontFamily: "sans-serif", padding: 12 }}>
      <h3>Count: {state.count}</h3>
      <button onClick={() => dispatch({ type: "dec" })}>-</button>
      <button onClick={() => dispatch({ type: "inc" })}>+</button>
      <button onClick={() => dispatch({ type: "reset" })}>Reset</button>
      <p>
        Step:{" "}
        <input type="number" value={state.step} style={{ width: 60 }}
          onChange={(e) => dispatch({ type: "setStep", step: Number(e.target.value) || 1 })} />
      </p>
    </div>
  );
}

const ThemeContext = createContext("light");

function Toolbar() {
  return <ThemedButton />;
}
function ThemedButton() {
  const theme = useContext(ThemeContext);
  const style = theme === "dark"
    ? { background: "#222", color: "#fff" }
    : { background: "#eee", color: "#111" };
  return <button style={{ ...style, padding: "8px 14px" }}>I am a {theme} button</button>;
}

function App() {
  const [theme, setTheme] = useState("light");
  return (
    <ThemeContext.Provider value={theme}>
      <div style={{ fontFamily: "sans-serif", padding: 12 }}>
        <button onClick={() => setTheme(theme === "light" ? "dark" : "light")}>Toggle theme</button>
        <div style={{ marginTop: 10 }}><Toolbar /></div>
      </div>
    </ThemeContext.Provider>
  );
}

topics.description:
Raw `Context.Provider` usage everywhere gets messy. The standard pattern is to encapsulate it.

### Pattern 1: provider component + custom hook

```jsx
const AuthContext = createContext(null);

export function AuthProvider({ children }) {
  const [user, setUser] = useState(null);
  const value = useMemo(() => ({ user, login: setUser, logout: () => setUser(null) }), [user]);
  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
}

export function useAuth() {
  const ctx = useContext(AuthContext);
  if (ctx === null) throw new Error("useAuth must be used inside AuthProvider");
  return ctx;
}
```

Benefits: consumers just call `useAuth()`, the context object stays private, and a missing provider fails loudly.

### Pattern 2: split state and dispatch

Put `state` in one context and `dispatch` in another. Components that only dispatch (buttons) do not re-render when state changes.

### Pattern 3: several small contexts

Instead of one giant `AppContext`, create `ThemeContext`, `AuthContext`, `CartContext`. Components subscribe only to what they need.

### Pattern 4: context + useReducer

A tiny store: reducer logic in the provider, `useCart()` exposes `{ state, dispatch }`. This is fine for small and medium apps.

### Performance tips

- Memoize the `value`.
- Pass `children` through the provider; they will not re-render when provider state changes if their element identity is unchanged.
- Move to Zustand/Redux when you need selectors.

examples.code:
const CountStateContext = createContext(null);
const CountDispatchContext = createContext(null);

function CountProvider({ children }) {
  const [count, dispatch] = useReducer((s, a) => (a === "inc" ? s + 1 : a === "reset" ? 0 : s), 0);
  return (
    <CountStateContext.Provider value={count}>
      <CountDispatchContext.Provider value={dispatch}>{children}</CountDispatchContext.Provider>
    </CountStateContext.Provider>
  );
}
function useCount() {
  const v = useContext(CountStateContext);
  if (v === null) throw new Error("useCount must be inside CountProvider");
  return v;
}
function useCountDispatch() {
  const d = useContext(CountDispatchContext);
  if (!d) throw new Error("useCountDispatch must be inside CountProvider");
  return d;
}

function Display() { return <h3>Count: {useCount()}</h3>; }
function Buttons() {
  const dispatch = useCountDispatch();
  console.log("Buttons rendered");
  return (
    <>
      <button onClick={() => dispatch("inc")}>+1</button>
      <button onClick={() => dispatch("reset")}>Reset</button>
    </>
  );
}

function App() {
  return (
    <CountProvider>
      <div style={{ fontFamily: "sans-serif", padding: 12 }}>
        <Display />
        <Buttons />
      </div>
    </CountProvider>
  );
}

function countPrimesBelow(n) {
  let count = 0;
  for (let i = 2; i < n; i++) {
    let isPrime = true;
    for (let j = 2; j * j <= i; j++) if (i % j === 0) { isPrime = false; break; }
    if (isPrime) count++;
  }
  return count;
}

function App() {
  const [limit, setLimit] = useState(20000);
  const [note, setNote] = useState("");

  const primes = useMemo(() => {
    console.log("computing primes below", limit);
    return countPrimesBelow(limit);
  }, [limit]);

  return (
    <div style={{ fontFamily: "sans-serif", padding: 12 }}>
      <button onClick={() => setLimit(limit + 10000)}>Limit: {limit} (click to raise)</button>
      <p>Primes below limit: <b>{primes}</b></p>
      <input value={note} onChange={(e) => setNote(e.target.value)} placeholder="Type here - no recompute" />
    </div>
  );
}

const Child = memo(function Child({ onAdd, label }) {
  console.log("Child rendered:", label);
  return <button onClick={onAdd}>{label}</button>;
});

function App() {
  const [count, setCount] = useState(0);
  const [text, setText] = useState("");

  const addStable = useCallback(() => setCount((c) => c + 1), []);
  const addUnstable = () => setCount((c) => c + 1);

  return (
    <div style={{ fontFamily: "sans-serif", padding: 12 }}>
      <p>Count: {count}</p>
      <Child onAdd={addStable} label="Stable (useCallback)" />
      <Child onAdd={addUnstable} label="Unstable (new fn each render)" />
      <p><input value={text} onChange={(e) => setText(e.target.value)} placeholder="type and watch console" /></p>
    </div>
  );
}

const Expensive = memo(function Expensive({ value }) {
  console.log("Expensive rendered with", value);
  return <p>Memoized child value: {value}</p>;
});

function Plain({ value }) {
  console.log("Plain rendered with", value);
  return <p>Plain child value: {value}</p>;
}

function App() {
  const [tick, setTick] = useState(0);
  return (
    <div style={{ fontFamily: "sans-serif", padding: 12 }}>
      <button onClick={() => setTick(tick + 1)}>Parent re-render ({tick})</button>
      <Expensive value={42} />
      <Plain value={42} />
    </div>
  );
}

function App() {
  const ref = useRef(null);
  const [width, setWidth] = useState(0);
  const [text, setText] = useState("Resize me by typing");

  useLayoutEffect(() => {
    setWidth(ref.current.getBoundingClientRect().width);
  }, [text]);

  return (
    <div style={{ fontFamily: "sans-serif", padding: 12 }}>
      <input value={text} onChange={(e) => setText(e.target.value)} />
      <div style={{ marginTop: 10 }}>
        <span ref={ref} style={{ background: "#fde68a", padding: 4, display: "inline-block" }}>{text}</span>
      </div>
      <p>Measured width: {Math.round(width)}px</p>
    </div>
  );
}

function Field({ label, hint }) {
  const id = useId();
  return (
    <div style={{ marginBottom: 10 }}>
      <label htmlFor={id} style={{ display: "block" }}>{label}</label>
      <input id={id} aria-describedby={id + "-hint"} />
      <small id={id + "-hint"} style={{ display: "block", color: "#666" }}>{hint}</small>
    </div>
  );
}

function App() {
  return (
    <div style={{ fontFamily: "sans-serif", padding: 12 }}>
      <Field label="First name" hint="As on your ID" />
      <Field label="Last name" hint="Family name" />
      <p style={{ fontSize: 12 }}>Click a label - the matching input gets focus.</p>
    </div>
  );
}

const ITEMS = Array.from({ length: 4000 }, (_, i) => "Item " + i);

function Heavy({ filter }) {
  const rows = [];
  for (let i = 0; i < ITEMS.length; i++) {
    if (ITEMS[i].includes(filter)) rows.push(<li key={i}>{ITEMS[i]}</li>);
  }
  return <ul style={{ maxHeight: 140, overflow: "auto" }}>{rows.slice(0, 300)}</ul>;
}

function App() {
  const [text, setText] = useState("");
  const [filter, setFilter] = useState("");
  const [isPending, startTransition] = useTransition();

  return (
    <div style={{ fontFamily: "sans-serif", padding: 12 }}>
      <input
        value={text}
        placeholder="filter, e.g. 99"
        onChange={(e) => {
          setText(e.target.value);
          startTransition(() => setFilter(e.target.value));
        }}
      />
      {isPending && <span> updating...</span>}
      <div style={{ opacity: isPending ? 0.5 : 1 }}>
        <Heavy filter={filter} />
      </div>
    </div>
  );
}

const SlowList = memo(function SlowList({ query }) {
  const items = [];
  for (let i = 0; i < 2500; i++) {
    const text = "Row " + i;
    if (text.includes(query)) items.push(<li key={i}>{text}</li>);
  }
  return <ul style={{ maxHeight: 120, overflow: "auto" }}>{items.slice(0, 200)}</ul>;
});

function App() {
  const [query, setQuery] = useState("");
  const deferred = useDeferredValue(query);
  const stale = query !== deferred;
  return (
    <div style={{ fontFamily: "sans-serif", padding: 12 }}>
      <input value={query} onChange={(e) => setQuery(e.target.value)} placeholder="Type to filter rows" />
      <div style={{ opacity: stale ? 0.5 : 1, transition: "opacity .2s" }}>
        <SlowList query={deferred} />
      </div>
    </div>
  );
}

// useSyncExternalStore is not in the pre-destructured list: take it from React
const { useSyncExternalStore } = React;

// An external store living outside React
const store = {
  value: 0,
  listeners: new Set(),
  get() { return store.value; },
  set(v) { store.value = v; store.listeners.forEach((l) => l()); },
  subscribe(cb) { store.listeners.add(cb); return () => store.listeners.delete(cb); },
};

function useStore() {
  return useSyncExternalStore(store.subscribe, store.get);
}

function Show() { return <p>Store value: {useStore()}</p>; }
function Controls() {
  const v = useStore();
  return <button onClick={() => store.set(v + 1)}>Increment store</button>;
}

function App() {
  return (
    <div style={{ fontFamily: "sans-serif", padding: 12 }}>
      <Show />
      <Show />
      <Controls />
    </div>
  );
}

topics.description:
By default a `ref` on a custom component does **not** give you a DOM node, because components are not DOM elements. In React 18 you wrap the child in **`forwardRef`** to pass the ref down to an inner element. In React 19, `ref` is just a regular prop for function components and `forwardRef` is no longer needed.

```jsx
const FancyInput = forwardRef(function FancyInput(props, ref) {
  return <input ref={ref} {...props} />;
});
// parent
const r = useRef(); <FancyInput ref={r} />; r.current.focus();
```

### Exposing a custom API

Handing out the raw DOM node lets the parent do anything. **`useImperativeHandle(ref, createHandle, deps)`** lets you expose only chosen methods:

```jsx
useImperativeHandle(ref, () => ({
  focus() { inner.current.focus(); },
  clear() { inner.current.value = ""; },
}), []);
```

### When to use

- Reusable input/design-system components that must support `.focus()`.
- Imperative actions that props cannot express well: `modal.open()`, `video.play()`, `scrollToItem(i)`.

### Prefer props when possible

If something can be a prop (`isOpen`), do that - it follows declarative data flow. Use imperative handles only for commands such as focus, scroll, play, or triggering an animation.

examples.code:
const { useImperativeHandle } = React;

const FancyInput = forwardRef(function FancyInput({ placeholder }, ref) {
  const inner = useRef(null);
  useImperativeHandle(ref, () => ({
    focus() { inner.current.focus(); },
    clear() { inner.current.value = ""; inner.current.focus(); },
  }), []);
  return <input ref={inner} placeholder={placeholder} />;
});

function App() {
  const boxRef = useRef(null);
  return (
    <div style={{ fontFamily: "sans-serif", padding: 12 }}>
      <FancyInput ref={boxRef} placeholder="Type something" />
      <button onClick={() => boxRef.current.focus()}>Focus</button>
      <button onClick={() => boxRef.current.clear()}>Clear</button>
    </div>
  );
}

topics.description:
Components share **UI** through other components. Custom hooks share **logic**: state, effects and refs that belong together. A custom hook is just a JavaScript function whose name starts with `use` and that calls other hooks.

```jsx
function useWindowWidth() {
  const [w, setW] = useState(window.innerWidth);
  useEffect(() => {
    const on = () => setW(window.innerWidth);
    window.addEventListener("resize", on);
    return () => window.removeEventListener("resize", on);
  }, []);
  return w;
}
```

### Key facts

- Each call creates **independent state**. Two components using `useWindowWidth()` do not share a state value (they share the *logic*).
- The `use` prefix lets React and ESLint apply the rules of hooks.
- A hook can take arguments and return anything: a value, a tuple `[value, setValue]`, or an object.
- Custom hooks can call other custom hooks and compose.

### When to extract a hook

- The same `useState` + `useEffect` combination appears in several components.
- A component mixes too much non-visual logic with markup.
- You want to test logic separately from UI.

### Naming and API design

Name by purpose, not implementation: `useOnlineStatus`, not `useEventListenerOnWindow`. Return arrays for 1-2 values the caller will rename (`[value, setValue]`), objects for more.

### Do not overdo it

Do not create lifecycle wrappers such as `useMount`; they hide dependencies. Extract hooks around real concrete use cases.

examples.code:
function useCounter(initial = 0, step = 1) {
  const [count, setCount] = useState(initial);
  const inc = useCallback(() => setCount((c) => c + step), [step]);
  const dec = useCallback(() => setCount((c) => c - step), [step]);
  const reset = useCallback(() => setCount(initial), [initial]);
  return { count, inc, dec, reset };
}

function Counter({ label, step }) {
  const { count, inc, dec, reset } = useCounter(0, step);
  return (
    <p>
      {label}: <b>{count}</b>{" "}
      <button onClick={dec}>-</button>
      <button onClick={inc}>+</button>
      <button onClick={reset}>reset</button>
    </p>
  );
}

function App() {
  return (
    <div style={{ fontFamily: "sans-serif", padding: 12 }}>
      <Counter label="Step 1" step={1} />
      <Counter label="Step 10" step={10} />
    </div>
  );
}

topics.description:
A very common custom hook: keep a piece of state (theme, filters, a draft) across page reloads by mirroring it into `localStorage`.

### Design

- **Read once** on first render with a lazy initializer.
- **Write** to storage whenever the value changes (in an effect).
- Store JSON, so use `JSON.stringify` / `JSON.parse` inside `try/catch` because storage can be unavailable (private mode, quota) and parsed data can be corrupt.
- Return the same API as `useState`: `[value, setValue]`.

```jsx
function useLocalStorage(key, initial) {
  const [value, setValue] = useState(() => {
    try {
      const raw = localStorage.getItem(key);
      return raw !== null ? JSON.parse(raw) : initial;
    } catch { return initial; }
  });
  useEffect(() => {
    try { localStorage.setItem(key, JSON.stringify(value)); } catch {}
  }, [key, value]);
  return [value, setValue];
}
```

### Improvements

- Listen to the `storage` event to sync across tabs (or use `useSyncExternalStore`).
- On the server (SSR) `localStorage` does not exist, so guard with `typeof window`.
- Support a functional updater - it works for free because you return the real `setValue`.

### Remember

`localStorage` is synchronous, string-only, limited to ~5 MB and readable by any script on your origin, so never store secrets or tokens that must be protected.

examples.code:
function useLocalStorage(key, initial) {
  const [value, setValue] = useState(() => {
    try {
      const raw = window.localStorage.getItem(key);
      return raw !== null ? JSON.parse(raw) : initial;
    } catch (e) {
      return initial;
    }
  });
  useEffect(() => {
    try { window.localStorage.setItem(key, JSON.stringify(value)); } catch (e) {}
  }, [key, value]);
  return [value, setValue];
}

function App() {
  const [note, setNote] = useLocalStorage("demo-note", "");
  const [count, setCount] = useLocalStorage("demo-count", 0);
  return (
    <div style={{ fontFamily: "sans-serif", padding: 12 }}>
      <textarea value={note} onChange={(e) => setNote(e.target.value)} placeholder="Notes are saved..." rows={3} />
      <p>
        Visits clicked: {count}{" "}
        <button onClick={() => setCount((c) => c + 1)}>+1</button>
      </p>
      <small>Reload the preview: values remain (if storage is allowed).</small>
    </div>
  );
}

topics.description:
Every data-fetching component repeats the same logic: three pieces of state, an effect, cleanup. Extract it into `useFetch(url)`.

```jsx
function useFetch(url) {
  const [state, setState] = useState({ data: null, error: null, loading: true });
  useEffect(() => {
    const controller = new AbortController();
    setState(s => ({ ...s, loading: true, error: null }));
    fetch(url, { signal: controller.signal })
      .then(r => { if (!r.ok) throw new Error("HTTP " + r.status); return r.json(); })
      .then(data => setState({ data, error: null, loading: false }))
      .catch(err => { if (err.name !== "AbortError") setState({ data: null, error: err, loading: false }); });
    return () => controller.abort();
  }, [url]);
  return state;
}
```

### Why it is built this way

- **AbortController** cancels stale requests when `url` changes or the component unmounts (no race condition, no memory leak).
- `fetch` does not reject on 404/500, so you must check `r.ok` yourself.
- The hook returns `{ data, error, loading }` so the component is purely presentational.

### Extending it

Add a `refetch` function, request options, caching keyed by URL, retries, or a `skip` argument for conditional fetching.

### When to stop

A hand-rolled `useFetch` has no cache, deduplication, background refresh or retry logic. For anything serious use **TanStack Query** or SWR (covered in the data fetching section). The hook is perfect for learning and small tools.

examples.code:
// Simulated network function: resolves after 400ms, rejects for "bad"
function fakeApi(path, signal) {
  return new Promise((resolve, reject) => {
    const t = setTimeout(() => {
      if (path === "bad") reject(new Error("Server error 500"));
      else resolve({ path, items: [path + "-1", path + "-2", path + "-3"] });
    }, 400);
    signal.addEventListener("abort", () => { clearTimeout(t); reject(new DOMException("Aborted", "AbortError")); });
  });
}

function useFetch(path) {
  const [state, setState] = useState({ data: null, error: null, loading: true });
  useEffect(() => {
    const controller = new AbortController();
    setState({ data: null, error: null, loading: true });
    fakeApi(path, controller.signal)
      .then((data) => setState({ data, error: null, loading: false }))
      .catch((err) => {
        if (err.name !== "AbortError") setState({ data: null, error: err, loading: false });
      });
    return () => controller.abort();
  }, [path]);
  return state;
}

function App() {
  const [path, setPath] = useState("users");
  const { data, error, loading } = useFetch(path);
  return (
    <div style={{ fontFamily: "sans-serif", padding: 12 }}>
      {["users", "posts", "bad"].map((p) => (
        <button key={p} onClick={() => setPath(p)} style={{ marginRight: 6 }}>{p}</button>
      ))}
      {loading && <p>Loading {path}...</p>}
      {error && <p style={{ color: "crimson" }}>{error.message}</p>}
      {data && <ul>{data.items.map((i) => <li key={i}>{i}</li>)}</ul>}
    </div>
  );
}

topics.description:
Debouncing waits until a value has stopped changing for N milliseconds before using it. It is perfect for search-as-you-type: instead of calling the API on every keystroke, call it once the user pauses.

### The hook

```jsx
function useDebounce(value, delay = 300) {
  const [debounced, setDebounced] = useState(value);
  useEffect(() => {
    const id = setTimeout(() => setDebounced(value), delay);
    return () => clearTimeout(id);
  }, [value, delay]);
  return debounced;
}
```

### How it works

Each time `value` changes, the effect cleanup cancels the previous timer and starts a new one. Only if the value stays unchanged for `delay` ms does the timer fire and update `debounced`.

### Using it

```jsx
const [query, setQuery] = useState("");
const debouncedQuery = useDebounce(query, 400);
useEffect(() => { search(debouncedQuery); }, [debouncedQuery]);
```

The input stays instant (bound to `query`), while the expensive work reacts to `debouncedQuery`.

### Debounce vs throttle

- **Debounce** - run after activity stops (search box, auto-save, resize end).
- **Throttle** - run at most once per interval (scroll, mouse move).

### Related: debounced callback

Sometimes you debounce a *function* instead of a value. Keep the timer id in a `useRef` and clear it before setting a new one.

examples.code:
function useDebounce(value, delay = 400) {
  const [debounced, setDebounced] = useState(value);
  useEffect(() => {
    const id = setTimeout(() => setDebounced(value), delay);
    return () => clearTimeout(id);
  }, [value, delay]);
  return debounced;
}

function App() {
  const [text, setText] = useState("");
  const debounced = useDebounce(text, 500);
  const [calls, setCalls] = useState(0);

  useEffect(() => {
    if (debounced) setCalls((c) => c + 1);
  }, [debounced]);

  return (
    <div style={{ fontFamily: "sans-serif", padding: 12 }}>
      <input value={text} onChange={(e) => setText(e.target.value)} placeholder="Type quickly..." />
      <p>Raw value: <b>{text}</b></p>
      <p>Debounced (500ms): <b>{debounced}</b></p>
      <p>Pretend API calls made: {calls}</p>
    </div>
  );
}

topics.description:
Small hooks remove boilerplate. Here are three of the most useful.

### useToggle

```jsx
function useToggle(initial = false) {
  const [on, setOn] = useState(initial);
  const toggle = useCallback(() => setOn(v => !v), []);
  return [on, toggle, setOn];
}
```

Used for modals, menus, dark mode, accordions.

### usePrevious

```jsx
function usePrevious(value) {
  const ref = useRef();
  useEffect(() => { ref.current = value; });
  return ref.current;
}
```

The ref is updated *after* render, so during the render it still holds the previous value. Handy for animations ("went up or down") and comparing props.

### useOnClickOutside

Closes dropdowns and popovers when the user clicks anywhere else.

```jsx
function useOnClickOutside(ref, handler) {
  useEffect(() => {
    const listener = (e) => {
      if (!ref.current || ref.current.contains(e.target)) return;
      handler(e);
    };
    document.addEventListener("mousedown", listener);
    return () => document.removeEventListener("mousedown", listener);
  }, [ref, handler]);
}
```

### Other popular hooks

`useWindowSize`, `useMediaQuery`, `useOnlineStatus`, `useInterval`, `useEventListener`, `useKeyPress`, `useCopyToClipboard`. Before writing your own, check libraries such as **usehooks-ts** or **react-use**.

### Tip

Wrap the handler passed to `useOnClickOutside` in `useCallback`, or store the latest handler in a ref, to avoid re-subscribing each render.

examples.code:
function useToggle(initial = false) {
  const [on, setOn] = useState(initial);
  const toggle = useCallback(() => setOn((v) => !v), []);
  return [on, toggle, setOn];
}
function usePrevious(value) {
  const ref = useRef();
  useEffect(() => { ref.current = value; });
  return ref.current;
}
function useOnClickOutside(ref, handler) {
  useEffect(() => {
    const listener = (e) => {
      if (!ref.current || ref.current.contains(e.target)) return;
      handler(e);
    };
    document.addEventListener("mousedown", listener);
    return () => document.removeEventListener("mousedown", listener);
  }, [ref, handler]);
}

function App() {
  const [open, toggle, setOpen] = useToggle(false);
  const [n, setN] = useState(0);
  const prev = usePrevious(n);
  const boxRef = useRef(null);
  const close = useCallback(() => setOpen(false), [setOpen]);
  useOnClickOutside(boxRef, close);

  return (
    <div style={{ fontFamily: "sans-serif", padding: 12 }}>
      <div ref={boxRef} style={{ display: "inline-block", position: "relative" }}>
        <button onClick={toggle}>Menu {open ? "^" : "v"}</button>
        {open && (
          <ul style={{ position: "absolute", margin: 0, padding: 8, listStyle: "none", border: "1px solid #ccc", background: "#fff", whiteSpace: "nowrap" }}>
            <li>Profile</li><li>Settings</li><li>Logout</li>
          </ul>
        )}
      </div>
      <p style={{ marginTop: 70 }}>
        n = {n}, previous = {String(prev)}{" "}
        <button onClick={() => setN(n + 1)}>n+1</button>
      </p>
    </div>
  );
}

function Dialog({ title, message, actions, children }) {
  return (
    <div className="dialog">
      <h3>{title}</h3>
      <p>{message}</p>
      {children}
      <div className="actions">{actions}</div>
    </div>
  );
}

function WelcomeDialog() {
  return (
    <Dialog
      title="Welcome"
      message="Thank you for visiting."
      actions={<button>Got it</button>}
    />
  );
}
function ConfirmDelete({ name }) {
  return (
    <Dialog
      title="Delete?"
      message={"Delete " + name + " permanently?"}
      actions={<><button>Cancel</button> <button style={{ color: "crimson" }}>Delete</button></>}
    >
      <small>This cannot be undone.</small>
    </Dialog>
  );
}

function App() {
  return <div style={{ fontFamily: "sans-serif", padding: 12 }}><WelcomeDialog /><ConfirmDelete name="report.pdf" /></div>;
}

function List({ items, renderItem, empty = <p>Nothing here</p> }) {
  if (items.length === 0) return empty;
  return <ul>{items.map((item, i) => <li key={item.id}>{renderItem(item, i)}</li>)}</ul>;
}

function Toggle({ children }) {
  const [on, setOn] = useState(false);
  return children({ on, toggle: () => setOn(!on) });
}

function App() {
  const fruits = [{ id: 1, name: "Apple" }, { id: 2, name: "Banana" }];
  return (
    <div style={{ fontFamily: "sans-serif", padding: 12 }}>
      <List items={fruits} renderItem={(f, i) => <b>{i + 1}. {f.name}</b>} />
      <List items={[]} renderItem={() => null} />
      <Toggle>
        {({ on, toggle }) => <button onClick={toggle}>Light is {on ? "ON" : "OFF"}</button>}
      </Toggle>
    </div>
  );
}

topics.description:
A **higher-order component** is a function `withX(Component)` that returns a new component adding behavior. It is function composition applied to components.

```jsx
function withLoading(Wrapped) {
  return function WithLoading({ loading, ...props }) {
    if (loading) return <p>Loading...</p>;
    return <Wrapped {...props} />;
  };
}
const UserListWithLoading = withLoading(UserList);
```

### Real-world HOCs

`connect()` in old Redux, `withRouter` in old React Router, `React.memo` (a built-in HOC), `withAuth(Page)`, `styled(Button)`.

### Rules for writing good HOCs

- **Do not mutate** the wrapped component; wrap it.
- **Pass through** all unrelated props with `{...props}`.
- **Never create HOCs inside render** - a new component type each render remounts the tree and loses state.
- Set a **`displayName`** (e.g. `withLoading(UserList)`) for DevTools.
- **Static methods and refs** are not forwarded automatically (use `forwardRef`, `hoist-non-react-statics`).
- Compose several HOCs with a `compose` helper.

### Downsides

- "Wrapper hell" in DevTools.
- Prop name collisions between HOCs.
- Harder to follow data flow and to type with TypeScript.

### Today

Hooks replaced most use cases. HOCs still appear in legacy code, libraries, and for cross-cutting concerns like auth guards, error boundary wrappers, and analytics.

examples.code:
function withHover(Wrapped) {
  function WithHover(props) {
    const [hover, setHover] = useState(false);
    return (
      <div onMouseEnter={() => setHover(true)} onMouseLeave={() => setHover(false)}>
        <Wrapped {...props} hover={hover} />
      </div>
    );
  }
  WithHover.displayName = "withHover(" + (Wrapped.displayName || Wrapped.name) + ")";
  return WithHover;
}

function Card({ title, hover }) {
  return (
    <div style={{ padding: 14, border: "2px solid", borderColor: hover ? "#0ea5e9" : "#ccc", borderRadius: 8, transition: ".2s" }}>
      {title} {hover && "(hovering)"}
    </div>
  );
}
const HoverCard = withHover(Card); // created OUTSIDE the component

function App() {
