topics.description:
Many bugs come from boolean soup: `isLoading`, `isError`, `isSuccess`, `isSubmitting` can all become `true` at once even though only one makes sense. A **finite state machine** says: the UI is in exactly **one state** at a time, and only certain **events** move it to another state.

### Example: fetch machine

```
idle --FETCH--> loading --RESOLVE--> success
                  |  \--REJECT--> error --RETRY--> loading
```

### In plain React

Use a single `status` string and a `useReducer` where each state only handles allowed events.

```jsx
function reducer(state, event) {
  switch (state.status) {
    case "idle":    return event.type === "FETCH" ? { status: "loading" } : state;
    case "loading": return event.type === "RESOLVE" ? { status: "success", data: event.data }
                         : event.type === "REJECT" ? { status: "error", error: event.error } : state;
    case "error":   return event.type === "RETRY" ? { status: "loading" } : state;
    default: return state;
  }
}
```

### Benefits

- **Impossible states become impossible.**
- Easy to draw, review and test.
- Clear places to put side effects (entering "loading" triggers the request).

### Tools

**XState** (with `@xstate/react`) provides full machines, statecharts, guards, actors and visualizers. Use it for wizards, checkout flows, media players and complex forms. For small cases a reducer is enough.

### Discriminated unions

In TypeScript model states as a union keyed by `status`, so `data` only exists in `success`.

examples.code:
function reducer(state, event) {
  switch (state.status) {
    case "idle":
      return event.type === "FETCH" ? { status: "loading" } : state;
    case "loading":
      if (event.type === "RESOLVE") return { status: "success", data: event.data };
      if (event.type === "REJECT") return { status: "error", error: event.error };
      return state;
    case "success":
    case "error":
      return event.type === "FETCH" ? { status: "loading" } : state;
    default:
      return state;
  }
}

function App() {
  const [state, dispatch] = useReducer(reducer, { status: "idle" });
  const attempt = useRef(0);

  useEffect(() => {
    if (state.status !== "loading") return;
    const t = setTimeout(() => {
      attempt.current += 1;
      if (attempt.current % 2 === 1) dispatch({ type: "REJECT", error: "Network down" });
      else dispatch({ type: "RESOLVE", data: "Here is your data" });
    }, 600);
    return () => clearTimeout(t);
  }, [state.status]);

  return (
    <div style={{ fontFamily: "sans-serif", padding: 12 }}>
      <p>Status: <b>{state.status}</b></p>
      <button onClick={() => dispatch({ type: "FETCH" })} disabled={state.status === "loading"}>
        {state.status === "error" ? "Retry" : "Fetch"}
      </button>
      {state.status === "success" && <p>{state.data}</p>}
      {state.status === "error" && <p style={{ color: "crimson" }}>{state.error}</p>}
    </div>
  );
}

function validate(v) {
  const e = {};
  if (!v.name.trim()) e.name = "Name is required";
  if (!/^\S+@\S+\.\S+$/.test(v.email)) e.email = "Enter a valid email";
  if (v.password.length < 6) e.password = "At least 6 characters";
  return e;
}

function Field({ label, name, type = "text", values, errors, touched, onChange, onBlur }) {
  const show = touched[name] && errors[name];
  return (
    <div style={{ marginBottom: 10 }}>
      <label htmlFor={name} style={{ display: "block" }}>{label}</label>
      <input id={name} name={name} type={type} value={values[name]} onChange={onChange} onBlur={onBlur}
        aria-invalid={!!show} aria-describedby={show ? name + "-err" : undefined} />
      {show && <div id={name + "-err"} role="alert" style={{ color: "crimson", fontSize: 13 }}>{errors[name]}</div>}
    </div>
  );
}

function App() {
  const [values, setValues] = useState({ name: "", email: "", password: "" });
  const [touched, setTouched] = useState({});
  const [done, setDone] = useState(false);
  const errors = validate(values);

  const onChange = (e) => setValues({ ...values, [e.target.name]: e.target.value });
  const onBlur = (e) => setTouched({ ...touched, [e.target.name]: true });
  const onSubmit = (e) => {
    e.preventDefault();
    setTouched({ name: true, email: true, password: true });
    if (Object.keys(errors).length === 0) setDone(true);
  };

  const shared = { values, errors, touched, onChange, onBlur };
  return (
    <form onSubmit={onSubmit} style={{ fontFamily: "sans-serif", padding: 12, maxWidth: 260 }} noValidate>
      <Field label="Name" name="name" {...shared} />
      <Field label="Email" name="email" {...shared} />
      <Field label="Password" name="password" type="password" {...shared} />
      <button type="submit">Create account</button>
      {done && <p style={{ color: "green" }}>Account created!</p>}
    </form>
  );
}

import { useForm } from "react-hook-form";

export default function SignUp() {
  const {
    register,
    handleSubmit,
    reset,
    formState: { errors, isSubmitting },
  } = useForm({ defaultValues: { email: "", password: "" }, mode: "onBlur" });

  const onSubmit = async (data) => {
    await fakeApi(data);   // your API call
    reset();
  };

  return (
    <form onSubmit={handleSubmit(onSubmit)} noValidate>
      <input
        placeholder="Email"
        {...register("email", {
          required: "Email is required",
          pattern: { value: /^\S+@\S+\.\S+$/, message: "Invalid email" },
        })}
      />
      {errors.email && <p role="alert">{errors.email.message}</p>}

      <input
        type="password"
        placeholder="Password"
        {...register("password", { required: "Required", minLength: { value: 6, message: "Min 6 chars" } })}
      />
      {errors.password && <p role="alert">{errors.password.message}</p>}

      <button disabled={isSubmitting}>{isSubmitting ? "Saving..." : "Sign up"}</button>
    </form>
  );
}

