}

// services/api.js - fetch wrapper
const BASE = import.meta.env.VITE_API_URL;

export async function api(path, { method = "GET", body, signal } = {}) {
  const res = await fetch(BASE + path, {
    method,
    headers: { "Content-Type": "application/json" },
    body: body ? JSON.stringify(body) : undefined,
    signal,
  });
  if (!res.ok) throw new Error(`Request failed: ${res.status}`);
  return res.status === 204 ? null : res.json();
}

// services/http.js - axios instance with interceptors
import axios from "axios";

export const http = axios.create({ baseURL: BASE, timeout: 8000 });

http.interceptors.request.use((config) => {
  const token = localStorage.getItem("token");
  if (token) config.headers.Authorization = `Bearer ${token}`;
  return config;
});

http.interceptors.response.use(
  (res) => res,
  (error) => {
    if (error.response?.status === 401) window.location.assign("/login");
    return Promise.reject(error);
  }
);

let attempts = 0;
function fakeLoad(kind) {
  return new Promise((resolve, reject) => {
    setTimeout(() => {
      attempts += 1;
      if (kind === "fail" && attempts % 2 === 1) reject(new Error("Network error"));
      else if (kind === "empty") resolve([]);
      else resolve(["Laptop", "Phone", "Tablet"]);
    }, 500);
  });
}

function App() {
  const [kind, setKind] = useState("ok");
  const [state, setState] = useState({ status: "idle", data: [], error: null });

  const load = useCallback(() => {
    setState((s) => ({ ...s, status: "loading", error: null }));
    fakeLoad(kind)
      .then((data) => setState({ status: "success", data, error: null }))
      .catch((e) => setState({ status: "error", data: [], error: e.message }));
  }, [kind]);

  useEffect(() => { attempts = 0; load(); }, [load]);

  return (
    <div style={{ fontFamily: "sans-serif", padding: 12 }}>
      {["ok", "empty", "fail"].map((k) => (
        <button key={k} onClick={() => setKind(k)} style={{ marginRight: 6, fontWeight: k === kind ? "bold" : "normal" }}>{k}</button>
      ))}
      <div aria-busy={state.status === "loading"} style={{ marginTop: 10 }}>
        {state.status === "loading" && <p>Loading...</p>}
        {state.status === "error" && (
          <p role="alert" style={{ color: "crimson" }}>
            {state.error} <button onClick={load}>Retry</button>
          </p>
        )}
        {state.status === "success" && state.data.length === 0 && <p>No products yet.</p>}
        {state.status === "success" && state.data.length > 0 && (
          <ul>{state.data.map((d) => <li key={d}>{d}</li>)}</ul>
        )}
      </div>
    </div>
  );
}

function fakeSearch(q, signal) {
  return new Promise((resolve, reject) => {
    const t = setTimeout(() => resolve(["result for " + q + " #1", "result for " + q + " #2"]), 500);
    signal.addEventListener("abort", () => {
      clearTimeout(t);
      reject(new DOMException("Aborted", "AbortError"));
    });
  });
}

function App() {
  const [q, setQ] = useState("");
  const [results, setResults] = useState([]);
  const [log, setLog] = useState([]);

  useEffect(() => {
    if (!q) { setResults([]); return; }
    const controller = new AbortController();
    fakeSearch(q, controller.signal)
      .then((r) => setResults(r))
      .catch((e) => {
        if (e.name === "AbortError") setLog((l) => [...l, "aborted: " + q]);
      });
    return () => controller.abort();
  }, [q]);

  return (
    <div style={{ fontFamily: "sans-serif", padding: 12 }}>
      <input value={q} onChange={(e) => setQ(e.target.value)} placeholder="Type fast..." />
      <ul>{results.map((r) => <li key={r}>{r}</li>)}</ul>
      <small>{log.join(" | ")}</small>
    </div>
  );
}

import { QueryClient, QueryClientProvider, useQuery, useMutation, useQueryClient } from "@tanstack/react-query";

const queryClient = new QueryClient();

export default function Root() {
  return (
    <QueryClientProvider client={queryClient}>
      <Todos />
    </QueryClientProvider>
  );
}

function Todos() {
  const qc = useQueryClient();

  const { data, isPending, isError, error, refetch } = useQuery({
    queryKey: ["todos"],
    queryFn: () => fetch("/api/todos").then((r) => {
      if (!r.ok) throw new Error("Failed to load");
      return r.json();
    }),
    staleTime: 60_000,
  });

  const addTodo = useMutation({
    mutationFn: (title) =>
      fetch("/api/todos", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ title }),
      }).then((r) => r.json()),
    onSuccess: () => qc.invalidateQueries({ queryKey: ["todos"] }),
  });

  if (isPending) return <p>Loading...</p>;
  if (isError) return <p>{error.message} <button onClick={() => refetch()}>Retry</button></p>;

  return (
    <>
      <ul>{data.map((t) => <li key={t.id}>{t.title}</li>)}</ul>
      <button onClick={() => addTodo.mutate("New task")} disabled={addTodo.isPending}>
        Add
      </button>
    </>
  );
}

const ALL = Array.from({ length: 53 }, (_, i) => "Item " + (i + 1));
const PAGE_SIZE = 8;

function App() {
  const [page, setPage] = useState(1);
  const totalPages = Math.ceil(ALL.length / PAGE_SIZE);
  const start = (page - 1) * PAGE_SIZE;
  const rows = ALL.slice(start, start + PAGE_SIZE);

  return (
    <div style={{ fontFamily: "sans-serif", padding: 12 }}>
      <ul>{rows.map((r) => <li key={r}>{r}</li>)}</ul>
      <button onClick={() => setPage((p) => p - 1)} disabled={page === 1}>Prev</button>
      <span style={{ margin: "0 10px" }}>Page {page} of {totalPages}</span>
      <button onClick={() => setPage((p) => p + 1)} disabled={page === totalPages}>Next</button>
    </div>
  );
}

let serverCalls = 0;
function fakeLikeApi() {
  return new Promise((resolve, reject) => {
    setTimeout(() => {
      serverCalls += 1;
      serverCalls % 3 === 0 ? reject(new Error("Server rejected")) : resolve();
    }, 700);
  });
}

function App() {
  const [likes, setLikes] = useState(10);
  const [liked, setLiked] = useState(false);
  const [error, setError] = useState("");
  const [busy, setBusy] = useState(false);

  async function toggle() {
    const snapshot = { likes, liked };
    setError("");
    setBusy(true);
    setLiked(!liked);
    setLikes(liked ? likes - 1 : likes + 1);
    try {
      await fakeLikeApi();
    } catch (e) {
      setLikes(snapshot.likes);
      setLiked(snapshot.liked);
      setError(e.message + " - rolled back");
    } finally {
      setBusy(false);
    }
  }

  return (
    <div style={{ fontFamily: "sans-serif", padding: 12 }}>
      <button onClick={toggle} disabled={busy}>{liked ? "Unlike" : "Like"} ({likes})</button>
      {busy && <small> saving...</small>}
      {error && <p style={{ color: "crimson" }}>{error}</p>}
    </div>
  );
}

