// A tiny store showing the same Redux ideas: actions -> reducer -> state
const StoreCtx = createContext(null);

function todosReducer(state, action) {
  switch (action.type) {
    case "todos/added": return [...state, { id: state.length + 1, text: action.payload, done: false }];
    case "todos/toggled": return state.map((t) => (t.id === action.payload ? { ...t, done: !t.done } : t));
    default: return state;
  }
}

function StoreProvider({ children }) {
  const [state, dispatch] = useReducer(todosReducer, [{ id: 1, text: "Read about Redux", done: false }]);
  return <StoreCtx.Provider value={{ state, dispatch }}>{children}</StoreCtx.Provider>;
}
const useStore = () => useContext(StoreCtx);

