    <StoreProvider>
      <div style={{ fontFamily: "sans-serif", padding: 12 }}>
        <AddTodo /><TodoList /><Counter />
      </div>
    </StoreProvider>
  );
}

topics.description:
### createAsyncThunk

For async work (API calls) inside Redux, RTK provides `createAsyncThunk`. It dispatches three actions automatically: `pending`, `fulfilled` and `rejected`. You handle them in `extraReducers`.

```js
export const fetchUsers = createAsyncThunk("users/fetch", async (_, { rejectWithValue }) => {
  const res = await fetch("/api/users");
  if (!res.ok) return rejectWithValue("Failed");
  return res.json();
});
```

State shape: `{ items: [], status: "idle" | "loading" | "succeeded" | "failed", error: null }`.

### RTK Query

Writing thunks, loading flags and caching by hand is repetitive. **RTK Query** is a data fetching and caching tool included in Redux Toolkit. You define an **API slice** with endpoints and it generates hooks.

```js
export const api = createApi({
  reducerPath: "api",
  baseQuery: fetchBaseQuery({ baseUrl: "/api" }),
  tagTypes: ["Post"],
  endpoints: (b) => ({
    getPosts: b.query({ query: () => "posts", providesTags: ["Post"] }),
    addPost: b.mutation({
      query: (body) => ({ url: "posts", method: "POST", body }),
      invalidatesTags: ["Post"],
    }),
  }),
});
export const { useGetPostsQuery, useAddPostMutation } = api;
```

### Features

- Automatic caching, deduplication and refetching.
- **Tags** for cache invalidation: a mutation invalidates tags, related queries refetch.
- Generated hooks with `isLoading`, `isFetching`, `error`, `data`.
- Optimistic updates via `onQueryStarted`.
- Polling, conditional `skip`, code-splitting with `injectEndpoints`.

### RTK Query vs TanStack Query

Both solve server state. Choose RTK Query if you already use Redux; otherwise TanStack Query is lighter and framework-agnostic.

examples.code:
import { configureStore } from "@reduxjs/toolkit";
import { createApi, fetchBaseQuery } from "@reduxjs/toolkit/query/react";

export const api = createApi({
  reducerPath: "api",
  baseQuery: fetchBaseQuery({ baseUrl: "/api" }),
  tagTypes: ["Post"],
  endpoints: (build) => ({
    getPosts: build.query({ query: () => "posts", providesTags: ["Post"] }),
    addPost: build.mutation({
      query: (body) => ({ url: "posts", method: "POST", body }),
      invalidatesTags: ["Post"],
    }),
  }),
});
export const { useGetPostsQuery, useAddPostMutation } = api;

export const store = configureStore({
  reducer: { [api.reducerPath]: api.reducer },
  middleware: (getDefault) => getDefault().concat(api.middleware),
});

// Component
function Posts() {
  const { data = [], isLoading, error } = useGetPostsQuery();
  const [addPost, { isLoading: saving }] = useAddPostMutation();
  if (isLoading) return <p>Loading...</p>;
  if (error) return <p>Failed</p>;
  return (
    <>
      <ul>{data.map((p) => <li key={p.id}>{p.title}</li>)}</ul>
      <button disabled={saving} onClick={() => addPost({ title: "Hello" })}>Add</button>
    </>
  );
}

const { useSyncExternalStore } = React;

function createStore(initializer) {
  let state;
  const listeners = new Set();
  const set = (partial) => {
    const next = typeof partial === "function" ? partial(state) : partial;
    state = { ...state, ...next };
    listeners.forEach((l) => l());
  };
  const get = () => state;
  state = initializer(set, get);
  const subscribe = (l) => { listeners.add(l); return () => listeners.delete(l); };
  return function useStore(selector = (s) => s) {
    return useSyncExternalStore(subscribe, () => selector(state));
  };
}

const useCart = createStore((set) => ({
  items: [],
  add: (name) => set((s) => ({ items: [...s.items, name] })),
  clear: () => set({ items: [] }),
}));

function Badge() {
