import { useState, useRef, type ChangeEvent, type FormEvent } from "react";

interface Todo {
  id: number;
  text: string;
  done: boolean;
}

interface TodoFormProps {
  onAdd: (text: string) => void;
  placeholder?: string;
}

function TodoForm({ onAdd, placeholder = "Add todo" }: TodoFormProps) {
  const [text, setText] = useState("");
  const inputRef = useRef<HTMLInputElement>(null);

  const handleChange = (e: ChangeEvent<HTMLInputElement>) => setText(e.target.value);
  const handleSubmit = (e: FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    if (!text.trim()) return;
    onAdd(text);
    setText("");
    inputRef.current?.focus();
  };

  return (
    <form onSubmit={handleSubmit}>
      <input ref={inputRef} value={text} onChange={handleChange} placeholder={placeholder} />
      <button>Add</button>
    </form>
  );
}

export default function App() {
  const [todos, setTodos] = useState<Todo[]>([]);
  const add = (text: string) => setTodos((t) => [...t, { id: Date.now(), text, done: false }]);
  return (
    <>
      <TodoForm onAdd={add} />
      <ul>{todos.map((t) => <li key={t.id}>{t.text}</li>)}</ul>
    </>
  );
}

type State = { count: number };
type Action =
  | { type: "inc" }
  | { type: "dec" }
  | { type: "set"; value: number };   // payload only on "set"

function reducer(state: State, action: Action): State {
  switch (action.type) {
    case "inc": return { count: state.count + 1 };
    case "dec": return { count: state.count - 1 };
    case "set": return { count: action.value };   // value is known to exist here
  }
}

interface SelectProps<T> {
  options: T[];
  value: T | null;
  onChange: (value: T) => void;
  getLabel: (option: T) => string;
  getValue: (option: T) => string | number;
}

export function Select<T>({ options, value, onChange, getLabel, getValue }: SelectProps<T>) {
  return (
    <select
      value={value ? String(getValue(value)) : ""}
      onChange={(e) => {
        const picked = options.find((o) => String(getValue(o)) === e.target.value);
