function App() {
  const [active, setActive] = useState(0);
  const refs = useRef([]);
  const baseId = useId();

  function onKeyDown(e) {
    let next = active;
    if (e.key === "ArrowRight") next = (active + 1) % TABS.length;
    else if (e.key === "ArrowLeft") next = (active - 1 + TABS.length) % TABS.length;
    else if (e.key === "Home") next = 0;
    else if (e.key === "End") next = TABS.length - 1;
    else return;
    e.preventDefault();
    setActive(next);
    refs.current[next].focus();
  }

  return (
    <div className="tabs">
      <div role="tablist" aria-label="Topics" onKeyDown={onKeyDown}>
        {TABS.map((t, i) => (
          <button key={t.id} role="tab" id={baseId + t.id} ref={(el) => (refs.current[i] = el)}
            aria-selected={i === active} aria-controls={baseId + t.id + "-panel"}
            tabIndex={i === active ? 0 : -1} onClick={() => setActive(i)}
            className={i === active ? "tab on" : "tab"}>
            {t.label}
          </button>
        ))}
      </div>
      <div role="tabpanel" id={baseId + TABS[active].id + "-panel"} aria-labelledby={baseId + TABS[active].id} className="panel">
        {TABS[active].content}
      </div>
    </div>
  );
}

