function range(a, b) { const r = []; for (let i = a; i <= b; i++) r.push(i); return r; }

function getPages(page, totalPages, siblings = 1) {
  const first = 1, last = totalPages;
  const left = Math.max(page - siblings, first);
  const right = Math.min(page + siblings, last);
  const pages = [];
  if (left > first) { pages.push(first); if (left > first + 1) pages.push("..."); }
  pages.push(...range(left, right));
  if (right < last) { if (right < last - 1) pages.push("..."); pages.push(last); }
  return pages;
}

function Pagination({ page, totalPages, onChange }) {
  const pages = getPages(page, totalPages);
  return (
    <nav aria-label="Pagination" className="pg">
      <button onClick={() => onChange(page - 1)} disabled={page === 1}>Prev</button>
      {pages.map((p, i) =>
        p === "..." ? <span key={"e" + i}>...</span> : (
          <button key={p} onClick={() => onChange(p)} aria-current={p === page ? "page" : undefined} className={p === page ? "on" : ""}>{p}</button>
        )
      )}
      <button onClick={() => onChange(page + 1)} disabled={page === totalPages}>Next</button>
    </nav>
  );
}

