          <span>
            <button onClick={() => dispatch({ type: "dec", id: i.id })} aria-label={"Decrease " + i.name}>-</button>
            {" "}{i.qty}{" "}
            <button onClick={() => dispatch({ type: "inc", id: i.id })} aria-label={"Increase " + i.name}>+</button>
            {" "}{money(i.price * i.qty)}{" "}
            <button onClick={() => dispatch({ type: "remove", id: i.id })}>x</button>
