function format(ms) {
  const cs = Math.floor((ms % 1000) / 10);
  const s = Math.floor(ms / 1000) % 60;
  const m = Math.floor(ms / 60000);
  return String(m).padStart(2, "0") + ":" + String(s).padStart(2, "0") + "." + String(cs).padStart(2, "0");
}

function App() {
  const [running, setRunning] = useState(false);
  const [elapsed, setElapsed] = useState(0);
  const [laps, setLaps] = useState([]);
  const startRef = useRef(0);

  useEffect(() => {
    if (!running) return;
    startRef.current = Date.now() - elapsed;
    const id = setInterval(() => setElapsed(Date.now() - startRef.current), 30);
    return () => clearInterval(id);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [running]);

  function lap() {
    setLaps((l) => [{ n: l.length + 1, at: elapsed, delta: elapsed - (l.length ? l[0].at : 0) }, ...l]);
  }
  function reset() {
    setRunning(false);
    setElapsed(0);
    setLaps([]);
  }

  return (
    <div className="sw">
      <div className="time">{format(elapsed)}</div>
      <button onClick={() => setRunning(!running)}>{running ? "Stop" : "Start"}</button>{" "}
      <button onClick={lap} disabled={!running}>Lap</button>{" "}
      <button onClick={reset} disabled={elapsed === 0}>Reset</button>
      <ol reversed>
        {laps.map((l) => <li key={l.n}>Lap {l.n}: {format(l.at)} (+{format(l.delta)})</li>)}
      </ol>
    </div>
  );
}

