const initial = {
  nextId: 4,
  columns: [
    { id: "todo", title: "To do", cardIds: [1, 2] },
    { id: "doing", title: "Doing", cardIds: [3] },
    { id: "done", title: "Done", cardIds: [] },
  ],
  cards: { 1: { id: 1, title: "Design UI" }, 2: { id: 2, title: "Write tests" }, 3: { id: 3, title: "Build API" } },
};

function reducer(state, action) {
  switch (action.type) {
    case "add": {
      const id = state.nextId;
      return {
        ...state,
        nextId: id + 1,
        cards: { ...state.cards, [id]: { id, title: action.title } },
        columns: state.columns.map((c) => (c.id === action.columnId ? { ...c, cardIds: [...c.cardIds, id] } : c)),
      };
    }
    case "move": {
      const from = state.columns.findIndex((c) => c.cardIds.includes(action.cardId));
      const to = from + action.dir;
      if (from === -1 || to < 0 || to >= state.columns.length) return state;
      return {
        ...state,
        columns: state.columns.map((c, i) => {
          if (i === from) return { ...c, cardIds: c.cardIds.filter((id) => id !== action.cardId) };
          if (i === to) return { ...c, cardIds: [...c.cardIds, action.cardId] };
          return c;
        }),
      };
    }
    case "delete": {
      const { [action.cardId]: removed, ...rest } = state.cards;
      return {
        ...state,
        cards: rest,
        columns: state.columns.map((c) => ({ ...c, cardIds: c.cardIds.filter((id) => id !== action.cardId) })),
      };
    }
    default:
      return state;
  }
}

function Column({ column, cards, dispatch }) {
  const [title, setTitle] = useState("");
  return (
    <section className="col" aria-label={column.title}>
      <h4>{column.title} ({cards.length})</h4>
      {cards.map((card) => (
        <div key={card.id} className="card">
          <span>{card.title}</span>
          <div>
            <button aria-label={"Move " + card.title + " left"} onClick={() => dispatch({ type: "move", cardId: card.id, dir: -1 })}>&lt;</button>
            <button aria-label={"Move " + card.title + " right"} onClick={() => dispatch({ type: "move", cardId: card.id, dir: 1 })}>&gt;</button>
            <button aria-label={"Delete " + card.title} onClick={() => dispatch({ type: "delete", cardId: card.id })}>x</button>
          </div>
        </div>
      ))}
      <form onSubmit={(e) => { e.preventDefault(); if (title.trim()) dispatch({ type: "add", columnId: column.id, title: title.trim() }); setTitle(""); }}>
        <input value={title} onChange={(e) => setTitle(e.target.value)} placeholder="+ Add card" />
      </form>
    </section>
  );
}

function App() {
  const [state, dispatch] = useReducer(reducer, initial);
  return (
    <div className="board">
      {state.columns.map((col) => (
        <Column key={col.id} column={col} cards={col.cardIds.map((id) => state.cards[id])} dispatch={dispatch} />
      ))}
    </div>
  );
}

